// Turns the report from ops_daily_report() into one chat message.
const r = $input.first().json;
const n = v => Number(v ?? 0).toLocaleString('en-US', { maximumFractionDigits: 2 });
const sign = v => (Number(v) >= 0 ? '+' : '') + n(v);
const lines = [
  '**Vaultrush report, last ' + r.hours + ' h**' + (r.maintenance_on ? '  (maintenance is ON)' : ''),
  'Players: ' + n(r.players_total) + ' in total, ' + n(r.new_players) + ' new, ' + n(r.active_players) + ' active',
  'Bets: ' + n(r.bets) + ', wagered ' + n(r.wagered) + ', paid out ' + n(r.paid_out) + ', house ' + sign(r.house_result),
];
const games = (r.by_game ?? []).slice(0, 5).map(g => g.game + ' ' + n(g.wagered) + ' (' + n(g.bets) + ' bets)');
if (games.length) lines.push('Top games: ' + games.join(', '));
if (r.biggest_win) lines.push('Biggest win: ' + r.biggest_win.name + ' won ' + n(r.biggest_win.payout) + ' on ' + r.biggest_win.game + ' (bet ' + n(r.biggest_win.amount) + ')');
lines.push('Coins in wallets: ' + n(r.coins_in_wallets) + '; items held: ' + n(r.items_held) + ' (worth ' + n(r.items_value) + ')');
lines.push('Free coins issued: ' + n(r.free_coins_issued) + '; added by hand: ' + n(r.coins_adjusted) + ' in ' + n(r.adjustments) + ' step(s)');
return [{ json: { message: lines.join('\n').slice(0, 1900) } }];
